    // Update velocity based on pressed keys
    state.dx = 0;
    state.dy = 0;
    if (keys.ArrowUp) state.dy = -state.speed;
    if (keys.ArrowDown) state.dy = state.speed;
    if (keys.ArrowLeft) state.dx = -state.speed;
    if (keys.ArrowRight) state.dx = state.speed;

    // Update position
    state.x += state.dx;
    state.y += state.dy;

    // Keep inside bounds
    if (state.x - state.radius < 0) state.x = state.radius;
    if (state.x + state.radius > canvas.width) state.x = canvas.width - state.radius;
    if (state.y - state.radius < 0) state.y = state.radius;
    if (state.y + state.radius > canvas.height) state.y = canvas.height - state.radius;

    // Move stars downward for a subtle background effect
    const starSpeed = 0.3;
    for (const star of stars) {
      star.y += starSpeed;
      if (star.y > canvas.height) {
        star.y = 0;
        star.x = Math.random() * canvas.width;
      }
    }
  }

